(7120732, 1086827, 30861, '<td valign="top">You ARE pretty good; this is GORGEOUS. I''m not sure it responds very directly to "textures" <i>per se</i>, which is probably why it didn''t crack top-5, but it''s spectacular :-)</td>', 'You ARE pretty good; this is GORGEOUS. I''m not sure it responds very directly to "textures" per se, which is probably why it didn''t crack top-5, but it''s spectacular :-)', '2013-10-23 00:47:09.000000', NULL, 0),
(7120774, 1086850, 16106, '<td valign="top">I always try to drop a comment on the shot that had the greatest disparity between my vote and the place it received. Sadly you get this challenge''s comment. I loved the density of textures and the solidity of the leaf in contrast to the sublimation of the bird, all hanging together in the same tonal range. It seems my enthusiasm was misplace. I thought this was a great shot. Keep it up.</td>', 'I always try to drop a comment on the shot that had the greatest disparity between my vote and the place it received. Sadly you get this challenge''s comment. I loved the density of textures and the solidity of the leaf in contrast to the sublimation of the bird, all hanging together in the same tonal range. It seems my enthusiasm was misplace. I thought this was a great shot. Keep it up.', '2013-10-23 01:42:38.000000', NULL, 0),
(7120799, 1086827, 37858, '<td valign="top">This was my favorite image in the challenge.  I love that there is so much to take in and examine.  Beautiful.</td>', 'This was my favorite image in the challenge.  I love that there is so much to take in and examine.  Beautiful.', '2013-10-23 03:01:26.000000', NULL, 0),
